insert into public.bcps_proud_point_legacy (source_row, school_name, school_location_nbr, slot, text, submitted_at, date_posted) values
(1, 'Indian Ridge Middle School', '3471', 1, 'Indian Ridge offers over 15 unique clubs and activities for students, including Book Club and Dungeons & Dragons Club, fostering creativity and leadership.', '2025-01-28 09:23:00-04', null),
(1, 'Indian Ridge Middle School', '3471', 2, 'IRMS helps our local community through multiple service-learning organizations including NJHS, Student Council, Harvest Drive, Peer Counseling, Children Helping Other Children, and FFEA.', '2025-01-28 09:23:00-04', null),
(1, 'Indian Ridge Middle School', '3471', 3, 'Students in our top-rated Jaguar Band represent IRMS in the Florida All State Middle School Band and Broward All County Honor Band.', '2025-01-28 09:23:00-04', null),
(1, 'Indian Ridge Middle School', '3471', 4, 'Our award-winning Journalism & Communications programs have brought home seven state and national awards, multiple honorable mentions, and features in local media.', '2025-01-28 09:23:00-04', null),
(1, 'Indian Ridge Middle School', '3471', 5, 'The Ridge’s student-led cultural programs include our annual Hispanic Heritage Festival and Black History Month Showcase.', '2025-01-28 09:23:00-04', null),
(2, 'Miramar Elementary', '0531', 1, 'Miramar Elementary School is a great place to B+', '2025-01-31 12:30:00-04', null),
(2, 'Miramar Elementary', '0531', 2, 'Miramar Elementary School stands for Justice at the MLK Parade!', '2025-01-31 12:30:00-04', null),
(2, 'Miramar Elementary', '0531', 3, 'Science Comes To Life!', '2025-01-31 12:30:00-04', null),
(2, 'Miramar Elementary', '0531', 4, 'At Miramar Elementary Fieldtrips are a part of our curriculum.', '2025-01-31 12:30:00-04', null),
(2, 'Miramar Elementary', '0531', 5, 'The Kindergarten Holiday Show is always a crowd pleaser! Students show off their artistic side through music.', '2025-01-31 12:30:00-04', null),
(3, 'Pasadena Lakes Elementary', '2071', 1, 'Our student population benefits from a culturally enriched environment with over 10 student-led clubs including Robotics Club, Debate Club, Book Club, Student Safety Patrols, S.A.V.E. Club, Yearbook/Photography Club and National Elementary Honor Society just to name a few that foster creativity and leadership skills', '2025-01-31 14:29:00-04', null),
(3, 'Pasadena Lakes Elementary', '2071', 2, 'Our PAWsome Buddies program develops a platform for social interaction, friendship building, and mutual learning experiences within our student population while promoting positive interactions between general education students and neurodiverse students in our special programs.', '2025-01-31 14:29:00-04', null),
(3, 'Pasadena Lakes Elementary', '2071', 3, 'Student Council student members have impacted the community with sponsoring a toy drive that collected over 540 toys and gift cards for patients and families at Joe DiMaggio Children’s Hospital.', '2025-01-31 14:29:00-04', null),
(3, 'Pasadena Lakes Elementary', '2071', 4, 'Boasting a state-of-the-art newscasting studio, our students produce the morning announcements daily for staff and peers.', '2025-01-31 14:29:00-04', null),
(3, 'Pasadena Lakes Elementary', '2071', 5, 'Our outstanding Media Specialist has earned the 2023-2024 Golden Library Award for her exemplary expertise with keeping the Media Center up to date with today’s state mandates for our students, to stay current with today’s world events, both digitally and with our book circulation.', '2025-01-31 14:29:00-04', null),
(4, 'Sawgrass Springs Middle', '3431', 1, '1. Eco-warriors in action - Our award-winning Environmental Science program takes learning beyond the classroom, with hands-on field trips to places like Sea Camp in the Florida Keys!', '2025-02-04 14:04:00-04', null),
(4, 'Sawgrass Springs Middle', '3431', 2, '2. Champions on the rise - Our boys'' soccer, boys'' basketball, and girls'' volleyball teams all battled their way to the district playoffs—proving that teamwork and talent go hand in hand.', '2025-02-04 14:04:00-04', null),
(4, 'Sawgrass Springs Middle', '3431', 3, '3. Teaching excellence at its finest - Our incredible literacy coach is a district finalist for Teacher of the Year, making us proud and proving that great teaching happens here!', '2025-02-04 14:04:00-04', null),
(4, 'Sawgrass Springs Middle', '3431', 4, '4. Endless ways to explore - With over 35 electives—from art and music to PE, chess, and e-sports—there’s something for every student to discover and love.', '2025-02-04 14:04:00-04', null),
(4, 'Sawgrass Springs Middle', '3431', 5, '5. A community united for the planet - Our Environmental Advisory Board—made up of former educators, city officials, district staff, parents, and business partners—helps drive our school''s green initiatives and eco-education forward!', '2025-02-04 14:04:00-04', null),
(5, 'Bair Middle', '2611', 1, 'We are a Verizon Innovative Learning School, we empower students and teachers with iPads, enhancing education through innovative technology and enriched learning experiences.', '2025-02-05 17:36:00-04', null),
(5, 'Bair Middle', '2611', 2, 'We are a Cambridge Assessment International School, we offer students a rigorous, high-quality education that paves the way for higher learning and a tuition-free college pathway.', '2025-02-05 17:36:00-04', null),
(5, 'Bair Middle', '2611', 3, 'As part of an exclusive pilot project with ReframeXR, our school integrates cutting-edge mixed reality goggles into the classroom, transforming learning through immersive and interactive experiences.', '2025-02-05 17:36:00-04', null),
(5, 'Bair Middle', '2611', 4, 'Our Montessori Magnet Program has been nationally recognized with the prestigious Magnet Schools of America Award of Merit for Excellence, highlighting our commitment to innovative and high-quality education.', '2025-02-05 17:36:00-04', null),
(5, 'Bair Middle', '2611', 5, 'Through the Amazon Future Engineer program, we provide a comprehensive childhood-to-career pathway that expands access to computer science education, empowering students from underserved and underrepresented communities with future-ready skills.', '2025-02-05 17:36:00-04', null),
(6, 'Hollywood Park Elementary', '1761', 1, '"Our SECME and Robotics program has received several District Innovation Awards, engaging students in advanced science and technology projects."', '2025-02-06 13:33:00-04', null),
(6, 'Hollywood Park Elementary', '1761', 2, '"Students in our Young Men of Purpose Mentoring club makes a tangible difference in our community by volunteering during parent engagement events."', '2025-02-06 13:33:00-04', null),
(6, 'Hollywood Park Elementary', '1761', 3, '"We are an A Rated school with a history of maintaining an A or B Rating during the last 5 years which is a testament to the hard work and dedication to academic excellence by our students and staff."', '2025-02-06 13:33:00-04', null),
(6, 'Hollywood Park Elementary', '1761', 4, '"We offer several student-led clubs, including robotics, Student Council, TV Production, and  Safety Patrols that  fostering creativity and leadership."', '2025-02-06 13:33:00-04', null),
(6, 'Hollywood Park Elementary', '1761', 5, 'Our District recognized Student Choir performs at least 3 times per year a during annual parent events and have developed students into State Award Winning Choir Participants.', '2025-02-06 13:33:00-04', null),
(7, 'Driftwood Middle', '0861', 1, 'Named a 2025 Top Magnet School of Excellence by Magnet School of America.', '2025-02-06 13:38:00-04', null),
(7, 'Driftwood Middle', '0861', 2, 'Winner of the 2024 "How Low Can You Go" Challenge, presented by The Miami Heat, as Broward County''s Most Sustainable School.', '2025-02-06 13:38:00-04', null),
(7, 'Driftwood Middle', '0861', 3, 'Our students have placed at the Broward Debate Championship Tournaments during the following school years; 2021-2022, 2022-2023, and 2023-2024.', '2025-02-06 13:38:00-04', null),
(7, 'Driftwood Middle', '0861', 4, 'We offer unique clubs and after school activities including Anime Club, First Priority, Orange Bowl Academy, as well as the prestigious, National Junior Honor Society, and Student Government.', '2025-02-06 13:38:00-04', null),
(7, 'Driftwood Middle', '0861', 5, 'At least one of our sports teams have been Division Champs every year for the last 10 years, and more specifically our Driftwood Basketball teams have been back-to-back final four in the county for the past 2 years.', '2025-02-06 13:38:00-04', null),
(8, 'James S. Rickards Middle', '2121', 1, 'Highest student achievement in the past 10 years in ELA learning gains.', '2025-02-06 14:01:00-04', null),
(8, 'James S. Rickards Middle', '2121', 2, 'Highest student achievement in the past 10 years in ELA lowest quartile.', '2025-02-06 14:01:00-04', null),
(8, 'James S. Rickards Middle', '2121', 3, 'Highest student achievement in the past 10 years in Math learning gains.', '2025-02-06 14:01:00-04', null),
