(8, 'James S. Rickards Middle', '2121', 5, 'Highest student achievement in the past 10 years in Science achievement.', '2025-02-06 14:01:00-04', null),
(9, 'Pines Middle', null, 1, 'Our 6-12 Collegiate Academy allows students to graduate with both a high school diploma and an Associate''s degree, saving families significant tuition costs and accelerating their path to a bachelor''s.', '2025-02-07 09:14:00-04', null),
(9, 'Pines Middle', null, 2, 'As a Cambridge-certified school, we offer a rigorous, internationally recognized curriculum that prepares students for success in higher education and a globalized world.', '2025-02-07 09:14:00-04', null),
(9, 'Pines Middle', null, 3, 'Our Aeronautics and Robotics programs provide hands-on experience in aviation principles, flight simulation, drone technology, and robotics, cultivating critical thinking, teamwork, and problem-solving skills while sparking interest in STEM careers and the aerospace industry through hands-on experience and competition participation.', '2025-02-07 09:14:00-04', null),
(9, 'Pines Middle', null, 4, 'Students in our IT Career Pathway, specializing in HTML & CSS and Microsoft Office, earn industry-recognized certifications as IT Specialists, giving them a competitive edge in the tech job market.', '2025-02-07 09:14:00-04', null),
(9, 'Pines Middle', null, 5, 'Our ''B'' rating from the state reflects our commitment to continuous improvement and demonstrates significant progress in student achievement and closing achievement gaps, as we strive for excellence.', '2025-02-07 09:14:00-04', null),
(10, 'Cypress Elementary', '1781', 1, 'Strong Academics & Support – At Cypress Elementary, we provide instruction in Reading, Math, Science, and Social Studies aligned with Florida B.E.S.T. Standards, with Response to Intervention (RTI) ensuring every student receives the support they need.', '2025-02-07 11:35:00-04', null),
(10, 'Cypress Elementary', '1781', 2, 'Specialized Programs – We offer Exceptional Student Education (ESE) programs, including Pre-K and an Autism Spectrum Program, along with Dual Language & ESOL programs that promote bilingualism and academic success.', '2025-02-07 11:35:00-04', null),
(10, 'Cypress Elementary', '1781', 3, 'Clubs & Leadership – Our students can participate in engaging activities such as Debate, Spanish, Gardening, Peace Club, 5000 Role Models, Student Council, and Safety Patrols.', '2025-02-07 11:35:00-04', null),
(10, 'Cypress Elementary', '1781', 4, 'Cultural & Community Engagement – Cypress Elementary is proud to host the World Language Competition in partnership with Broward Schools’ ESOL Department, celebrating diversity and language learning.', '2025-02-07 11:35:00-04', null),
(10, 'Cypress Elementary', '1781', 5, 'Campus Enhancements & Technology – Through the SMART Program, we have invested over $3.7 million in upgrades, including a renovated media center, new technology, playground equipment, a digital marquee, and improved HVAC systems.', '2025-02-07 11:35:00-04', null),
(11, 'Griffin Elementary', '2851', 1, 'We are recognized as a Florida Green School with a Bronze Designation.', '2025-02-07 13:15:00-04', null),
(11, 'Griffin Elementary', '2851', 2, 'We have won the P3 Eco Challenge consecutively in various categories over the past decade.', '2025-02-07 13:15:00-04', null),
(11, 'Griffin Elementary', '2851', 3, 'We have been an "A" school for 22 consecutive years.', '2025-02-07 13:15:00-04', null),
(11, 'Griffin Elementary', '2851', 4, 'Many of our clubs have been recognized by the district in tournaments and contests.', '2025-02-07 13:15:00-04', null),
(11, 'Griffin Elementary', '2851', 5, 'We have a very active and passionate PTA that supports our school, students, and staff.', '2025-02-07 13:15:00-04', null),
(12, 'Walter C. Young Middle', '3001', 1, '"A" rated school for the 2023-2024 school year', '2025-02-07 14:37:00-04', null),
(12, 'Walter C. Young Middle', '3001', 2, '99% pass rate on High School EOC''s', '2025-02-07 14:37:00-04', null),
(12, 'Walter C. Young Middle', '3001', 3, 'Top 5 in ELA Learning Gains for Lowest 25%', '2025-02-07 14:37:00-04', null),
