(22, 'Boulevard Heights Elementary', '0971', 3, 'Bobcat Buddies Mentors – Supporting students through mentorship and leadership.', '2025-03-24 19:28:00-04', null),
(22, 'Boulevard Heights Elementary', '0971', 4, 'No Place for Hate School – Committed to fostering a respectful and bully-free environment.', '2025-03-24 19:28:00-04', null),
