(32, 'Colbert Museum Magnet', '0231', 3, 'Awarding winning Engineering Club - The most successful elementary SECME program in Broward County. Most recently, students placed first overall in the county in the 2024 Olympiad.', '2025-04-03 10:39:00-04', null),
(32, 'Colbert Museum Magnet', '0231', 4, 'Early Learning Opportunities – We offer early learning opportunities through our Head Start and Pre-K special programs, that allow students to begin their academic journey as early as 3 years old. Our early learning opportunities specialize in literacy and servicing students with exceptionalities.', '2025-04-03 10:39:00-04', null),
