(38, 'Forest Hills Elementary', '2631', 1, 'Our school garnered an A rating this year due to personalized instruction and high expectations for all.', '2025-04-04 14:38:00-04', null),
(38, 'Forest Hills Elementary', '2631', 2, 'Parental involvement is an integral component and a key element to our school''s success.', '2025-04-04 14:38:00-04', null),
(38, 'Forest Hills Elementary', '2631', 3, 'Principal Rothman’s Rangers is a mentoring group to motivate students in grades 3-5 to meet their end of year learning goals and enthusiastically take accountability and ownership of their daily actions leading towards their personal goals.', '2025-04-04 14:38:00-04', null),
(38, 'Forest Hills Elementary', '2631', 4, 'Our 5th grade student council members are actively engaged in mentoring their younger peers to acquire the necessary reading skills to successfully reach their end of year reading goals.', '2025-04-04 14:38:00-04', null),
(38, 'Forest Hills Elementary', '2631', 5, 'Our Debate students in grades 3-5 won medals in interpretation and public forum competing against other students in the North Region.', '2025-04-04 14:38:00-04', null),
(38, 'Forest Hills Elementary', '2631', 6, 'FHE students engage in project-based learning entering their projects in various contests including the City of Coral Springs MLK contest placing Best in Show, 1st, 2nd, 3rd Place in Literary and 1st and 2nd place in Art category amongst all Coral Springs schools.', '2025-04-04 14:38:00-04', null),
(39, 'Banyan Elementary', '2001', 1, 'A-Rated School: Our commitment to academic excellence has earned us Florida’s highest rating, reflecting the hard work of our students, staff, and families.', '2025-04-04 14:55:00-04', null),
(39, 'Banyan Elementary', '2001', 2, 'Cambridge School - Global Learning Program: As part of the prestigious Cambridge International Education program, we promote global-mindedness, critical thinking, and academic rigor across all grade levels.', '2025-04-04 14:55:00-04', null),
(39, 'Banyan Elementary', '2001', 3, 'Student-Run Broadcast Journalism Studio: Banyan students lead daily news broadcasts in a custom-designed media room featuring green screen technology, cameras, and editing tools — building communication skills, creativity, and confidence.', '2025-04-04 14:55:00-04', null),
(39, 'Banyan Elementary', '2001', 4, 'Banyan’s Book Club & Battle of the Books Competition: Our 3rd–5th grade Book Club meets weekly and culminates in a high-energy, school-designed competition that challenges comprehension, teamwork, and a true love of literature.', '2025-04-04 14:55:00-04', null),
(39, 'Banyan Elementary', '2001', 5, 'Innovation in Every Corner: Whether through tech-rich classrooms, creative enrichment opportunities, or leadership-driven initiatives, Banyan is a school where innovation thrives and every learner shines.', '2025-04-04 14:55:00-04', null),
(39, 'Banyan Elementary', '2001', 6, 'All-in-One Afterschool Experience: Our school-operated aftercare program is tailored to Banyan students and families — combining homework support, extracurricular enrichment, and school-provided dinner in one seamless, supportive environment.', '2025-04-04 14:55:00-04', null),
(40, 'North Side Elementary', '0041', 1, 'As a proud Florida Power Library School, our students shine beyond the classroom—and it all begins in our library —an innovative, student-centered space that inspires creativity, collaboration, and a love for reading and learning.', '2025-04-04 16:22:00-04', null),
(40, 'North Side Elementary', '0041', 2, '100% of our classrooms are furnished with a laptop for each child and a high tech Recordex.', '2025-04-04 16:22:00-04', null),
(40, 'North Side Elementary', '0041', 3, '80% of our students shine in 12 active clubs like STEM, 5000 Role Models, Debate, Percussion, and Garden Club. From coding and building to gardening and performing, our Shining Stars are growing as leaders. 💡📚🚀🌱🎶', '2025-04-04 16:22:00-04', null),
(40, 'North Side Elementary', '0041', 4, 'From engaging STEM challenges to programming VEX Robotics and piloting drones, our students are building real-world skills through hands-on learning.', '2025-04-04 16:22:00-04', null),
(40, 'North Side Elementary', '0041', 5, 'Our beautified courtyard serves as the focal point of our school, providing a versatile space for outdoor activities and a dynamic learning environment where students explore the wonders of science and nature.', '2025-04-04 16:22:00-04', null),
(40, 'North Side Elementary', '0041', 6, 'Our school is our strong sense of community, where dedicated teachers, engaged students, and supportive families work together to create a nurturing and high-achieving learning environment.', '2025-04-04 16:22:00-04', null),
