(54, 'South Broward High', '0171', 1, 'B-Rated School — South Broward High is on track to earn a B for it''s school grade, a reflection of our commitment to academic excellence through rigorous instruction and a supportive environment.', '2025-07-02 11:56:00-04', null),
(54, 'South Broward High', '0171', 2, '#1 Public Marine Magnet Program — As Florida’s first public high school Marine Magnet program, we offer hands-on learning with support from partners like NSU, UF, and Yamaha, preparing students for both college and careers.', '2025-07-02 11:56:00-04', null),
(54, 'South Broward High', '0171', 3, 'iCan Magnet Program — Our iCAN Magnet connects students with real-world pathways in seven robust academies focusing in Education, Business, Computer Science, Engineering, Health Sciences, and Arts & Entertainment through hands-on learning, industry certification opportunities, and personalized guidance, students are set up for future success.', '2025-07-02 11:56:00-04', null),
(54, 'South Broward High', '0171', 4, '500+ AICE Diploma Recipients — Our growing Cambridge program has awarded over 500 AICE diplomas since its launch… And we’re committed to scaling the program as the only BCPS high school to offer both A-Level History and Marine Science.', '2025-07-02 11:56:00-04', null),
(54, 'South Broward High', '0171', 5, '60+ Student-Led Organizations — From advocacy groups to nationally recognized Honor Societies, our students lead with vision, voice, and purpose.', '2025-07-02 11:56:00-04', null),
(54, 'South Broward High', '0171', 6, 'South Broward High is one of the most diverse schools in Broward County, celebrating a rich tapestry of cultures, languages, and perspectives. This diversity fosters global awareness, empathy, and unity—preparing students to thrive in an interconnected world.', '2025-07-02 11:56:00-04', null),
