(177, 'Everglades Elementary', '2942', 5, 'Our school offers a broad range of student clubs, including Drama, Art, Broadcasting, SAVE Promise, Speech and Debate, Student Council, Safety Patrol, and Inclusion. These extracurricular opportunities empower students to pursue their interests and develop valuable new skills, enriching their overall school experience.', '2025-12-15 12:25:00-04', null),
