(261, 'Crystal Lake Middle', '1871', 3, 'Engineering and Environmental Science - Scholars dive into coding and robotics, gaining hands-on skills in cutting-edge technology.', '2026-05-01 08:41:00-04', '2026-05-05'),
(261, 'Crystal Lake Middle', '1871', 4, 'Civil Air Patrol - The only middle school Civil Air Patrol program in Broward County—where students don’t just learn about aviation, they live it.', '2026-05-01 08:41:00-04', '2026-05-05'),
